const stripAccents = (value) => String(value || '')
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '');

const normalizeKnownCandidate = (value) => stripAccents(value)
  .replace(/^SHA256_/i, '')
  .toUpperCase()
  .replace(/[^A-Z0-9_]+/g, ' ')
  .trim();

const matchKnownFamily = (value) => {
  const normalized = normalizeKnownCandidate(value);
  if (!normalized) {
    return '';
  }

  const compact = normalized.replace(/[\s_]+/g, '');
  if (KNOWN_FAMILY_CORES.has(compact)) {
    return compact;
  }

  const tokens = normalized.split(/\s+/).filter(Boolean);
  for (const token of tokens) {
    const direct = token.replace(/[^A-Z0-9]+/g, '');
    if (KNOWN_FAMILY_CORES.has(direct)) {
      return direct;
    }
  }

  for (const family of KNOWN_FAMILY_CORES) {
    if (compact.includes(String(family).replace(/_/g, ''))) {
      return family;
    }
  }

  return '';
};

const normalizeThreatCore = (value) => {
  let text = stripAccents(value)
    .replace(/^SHA256_/i, '')
    .toLowerCase()
    .replace(/[^a-z0-9\s_-]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

  text = text
    .replace(/^(nueva|nuevo|nuevas|nuevos)\s+actividad(?:es)?\s+del\s+malware\s+/i, '')
    .replace(/^actualizacion\s+del\s+troyano\s+bancario\s+/i, '')
    .replace(/^actualizacion\s+de\s+/i, '')
    .replace(/^actividad(?:es)?\s+del\s+malware\s+/i, '')
    .replace(/^actividad(?:es)?\s+de\s+/i, '')
    .replace(/^troyano\s+bancario\s+/i, '')
    .replace(/^malware\s+/i, '')
    .replace(/^amenaza\s+/i, '')
    .trim();

  if (/\bvidar\b/.test(text) && /\bstealer\b/.test(text)) {
    return 'VIDARSTEALER';
  }

  if (/\bhorabot\b/.test(text)) {
    return 'HORABOT';
  }

  const knownFamily = matchKnownFamily(text);
  if (knownFamily) {
    return knownFamily;
  }

  const stopwords = new Set(['de', 'del', 'la', 'el', 'los', 'las', 'y', 'the', 'campaign', 'campana', 'campaigns']);
  const tokens = text
    .split(/\s+/)
    .map(token => token.trim())
    .filter(token => token && !stopwords.has(token));

  const compact = tokens.join('').replace(/[^a-z0-9]+/g, '');
  return compact ? compact.toUpperCase() : 'UNKNOWN';
};

const formatThreatTag = (value) => {
  const core = normalizeThreatCore(value);
  return core && core !== 'UNKNOWN' ? `SHA256_${core}` : '';
};

const sha256Regex = /^[a-f0-9]{64}$/i;
const uniq = arr => [...new Set((Array.isArray(arr) ? arr : []).map(x => String(x).trim()).filter(Boolean))];

const ips = uniq(data.ips);
const domains = uniq(data.domains).map(x => x.toLowerCase());
const urls = uniq(data.urls);

const contextThreat = formatThreatTag(items[0]?.json?.context_threat_name || '');
const defaultThreat = formatThreatTag(data.default_threat_name || '') || contextThreat;
const unresolvedHashes = [];

const sha_lines = uniq((Array.isArray(data.sha256) ? data.sha256 : [])
  .map(x => {
    const hash = String(x?.value || '').trim().toLowerCase();
    const threat = formatThreatTag(x?.threat_name || '') || defaultThreat;

    if (!sha256Regex.test(hash)) {
      return null;
    }

    if (!threat) {
      unresolvedHashes.push(hash);
      return null;
    }

    return `${hash} ${threat}`;
  })
  .filter(Boolean));

if (unresolvedHashes.length > 0) {
  throw new Error(`Unable to resolve canonical threat name for ${unresolvedHashes.length} SHA256 indicator(s): ${unresolvedHashes.join(', ')}`);
}

return [{
  json: {
    ips,
    domains,
    urls,
    default_threat_name: defaultThreat || null,
    sha_lines
  }
}];

