  const raw = String(value || '').trim();
  if (!raw) {
    return '';
  }

  const angleMatch = raw.match(/<([^<>\s@]+@[^<>\s@]+)>/);
  if (angleMatch?.[1]) {
    return angleMatch[1].toLowerCase();
  }

  const directMatch = raw.match(/([A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,})/i);
  return directMatch?.[1]?.toLowerCase() || '';
};

