  '',
  sourceLabel + ': ' + sourceValue,
  '',
  ...actionShaLines,
  '',
  'Total procesados: ' + totalActionCount,
  'Nuevos: ' + newShaCount,
  'Corregidos: ' + correctedShaCount,
  '',
  footerText
].join('\n');

return {
