  const normalized = rawTag
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/^SHA256_/i, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();

  if (!normalized || normalized === 'unknown') {
    return 'UNKNOWN';
  }

  if (/\bvidar\b/.test(normalized) && /\bstealer\b/.test(normalized)) {
    return 'VIDARSTEALER';
  }

  if (/\bhorabot\b/.test(normalized)) {
