  const byHash = new Map();
  const order = [];
  const rawHashes = new Set((String(inputRaw || '').match(/[a-f0-9]{64}/gi) || []).map(x => x.toLowerCase()));

  for (const line of String(inputRaw || '').split(/\r?\n/)) {
    const trimmed = String(line || '').trim();
    const match = trimmed.match(/^([a-f0-9]{64})\s+(.+)$/i);

    if (!match) {
      continue;
    }

    const hash = match[1].toLowerCase();
    const tag = canonicalTag(match[2]) || 'SHA256_UNKNOWN';

    if (!byHash.has(hash)) {
      order.push(hash);
    }

    byHash.set(hash, tag);
  }

  return { byHash, order, rawHashes };
};

