const byHash = parsed.byHash;
const order = parsed.order;
const rawHashes = parsed.rawHashes;
const existingCount = byHash.size;

if (existingCount < MIN_EXPECTED_EXISTING_SHA_COUNT) {
  throw new Error(`Current blocklist appears unexpectedly small (${existingCount} hashes), abort write`);
}

if (rawHashes.size > 0 && existingCount < rawHashes.size) {
  throw new Error(`Unable to safely parse existing blocklist (${existingCount}/${rawHashes.size} hashes), abort write`);
}

