  const match = String(line).trim().match(/^([a-f0-9]{64})\s+(.+)$/i);

  if (!match) {
    continue;
  }

  const hash = match[1].toLowerCase();
  const incomingTag = canonicalTag(match[2]);

  if (!incomingTag) {
    throw new Error(`Incoming SHA256 indicator without canonical threat tag: ${hash}`);
  }

  const existingTag = byHash.get(hash);

  if (!existingTag) {
    byHash.set(hash, incomingTag);
    order.push(hash);
    addedCount++;
    continue;
  }

  if (existingTag !== incomingTag) {
    byHash.set(hash, incomingTag);
    correctedCount++;
  }
}

