const canonicalTag = (value) => {
  const core = normalizeThreatCore(value);
  return core && core !== 'UNKNOWN' ? `SHA256_${core}` : '';
};

const parseExisting = (raw) => {
  const existing = new Map();
  for (const line of String(raw || '').split(/\r?\n/)) {
    const match = String(line).trim().match(/^([a-f0-9]{64})\s+(.+)$/i);
    if (!match) {
      continue;
    }
    existing.set(match[1].toLowerCase(), canonicalTag(match[2]) || 'SHA256_UNKNOWN');
  }
  return existing;
};

