const items = $input.all();
const results = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const binaryKeys = Object.keys(item.binary ?? {});
  const binaryProperty = binaryKeys.includes('data') ? 'data' : binaryKeys[0];

  if (!binaryProperty) {
    throw new Error(`Input item ${i} does not contain binary data`);
  }

  const binary = item.binary?.[binaryProperty];
  const binaryData = binary?.data;

  if (typeof binaryData !== 'string' || !binaryData.length) {
    throw new Error(`Binary property ${binaryProperty} does not contain inline base64 data`);
  }

  const buffer = Buffer.from(binaryData, 'base64');

  results.push({
    json: {
      current_raw: buffer.toString('utf8')
    }
  });
}

return results;

